package com.slayerclog;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

/** Settings. Never change a keyName: saved settings are stored under it. */
@ConfigGroup(SlayerClogConfig.GROUP)
public interface SlayerClogConfig extends Config
{
	String GROUP = "slayerclog";

	// Superior options sit under their own heading, below the general options.
	@ConfigSection(
		name = "Superiors",
		description = "Superior slayer monster drops and counts.",
		position = 10
	)
	String SUPERIOR_SECTION = "superiors";

	@ConfigItem(
		keyName = "mortimerView",
		name = "Compare Mortimer options",
		description = "Compare the tasks Mortimer offers.",
		position = 1
	)
	default boolean mortimerView()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showOnlyUnobtained",
		name = "Hide obtained items",
		description = "Only list items you still need.",
		position = 2
	)
	default boolean showOnlyUnobtained()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showDropRates",
		name = "Show drop rates",
		description = "Show each item's drop rate, e.g. (1:512).",
		position = 3
	)
	default boolean showDropRates()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showQuantities",
		name = "Show logged quantities",
		description = "Show how many of each item you have logged.",
		position = 4
	)
	default boolean showQuantities()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showKillCounts",
		name = "Show kill counts",
		description = "Show your kill count for each task and boss.",
		position = 5
	)
	default boolean showKillCounts()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSuperior",
		name = "Show superior drops",
		description = "Include the Superior section.",
		position = 11,
		section = SUPERIOR_SECTION
	)
	default boolean showSuperior()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSuperiorTracked",
		name = "Superiors per task",
		description = "Show how many superiors you have seen on each task.",
		position = 12,
		section = SUPERIOR_SECTION
	)
	default boolean showSuperiorTracked()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showSuperiorTotal",
		name = "Superiors across all tasks",
		description = "Show your total superior kills.",
		position = 13,
		section = SUPERIOR_SECTION
	)
	default boolean showSuperiorTotal()
	{
		return true;
	}
}

package com.slayerclog;

import com.slayerclog.task.KillCountTracker;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.Value;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/** Sidebar panel. */
class SlayerClogPanel extends PluginPanel
{
	/** A single collection log item row. */
	@Value
	static class ItemRow
	{
		int itemId;
		String name;
		boolean obtained;
		int quantity;
		boolean synced;
		/** Drop rate from the mapping, or null when unknown. */
		String rate;
		/** Collection log page this item is logged on, shown as a tooltip on its status. */
		String page;
	}

	/** One monster version of a task with its item rows. */
	@Value
	static class Section
	{
		String monster;
		List<ItemRow> rows;
		/** Kill count for this monster, or null when unknown or hidden by config. */
		Integer killCount;
		/** Superior section only: superiors seen on this task by the plugin's own tally, or null if hidden. */
		Integer superiorsHere;
		/** Superior section only: superiors killed on all tasks, from the Slayer kill log, or null. */
		Integer superiorsTotal;
		/** The task (or Mortimer option) this section belongs to, named in the per-task superiors line. */
		String task;
	}

	/** A Mortimer option: an offered task name and its per-monster sections. */
	@Value
	static class Option
	{
		String name;
		List<Section> sections;
		/** Kill count for this task from the Slayer kill log, or null when unknown or hidden by config. */
		Integer killCount;
	}

	private static final Color OBTAINED = new Color(76, 175, 80);
	private static final Color MISSING = new Color(160, 160, 160);
	private static final Color WARN = new Color(220, 138, 0);

	private final ItemManager itemManager;
	private final SlayerClogConfig config;
	private final JPanel content = new JPanel();

	SlayerClogPanel(ItemManager itemManager, SlayerClogConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		add(content, BorderLayout.NORTH);

		showMessage("No active slayer task.", "Get a slayer task to see its collection log progress.");
	}

	void showMessage(String title, String subtitle)
	{
		content.removeAll();
		content.add(titleLabel(title));
		if (subtitle != null)
		{
			content.add(wrappedText(subtitle, MISSING));
		}
		refresh();
	}

	/** Current-task view, broken down per monster version. */
	void showTask(String taskName, int amount, String location, List<Section> sections, Integer killCount)
	{
		content.removeAll();
		content.add(titleLabel(amount > 0 ? taskName + " (" + amount + ")" : taskName));
		if (killCount != null)
		{
			// the title's brackets already hold the kills remaining, so the kill count gets its own line
			content.add(wrappedText("Kill count: " + formatKills(killCount), MISSING));
		}
		if (location != null)
		{
			content.add(wrappedText(location, MISSING));
		}

		if (sections.isEmpty())
		{
			content.add(wrappedText("No collection log items are mapped for this task yet.", MISSING));
			refresh();
			return;
		}

		final List<ItemRow> all = new ArrayList<>();
		for (Section section : sections)
		{
			all.addAll(section.getRows());
			content.add(sectionPanel(section));
		}

		// only a sync prompt; each section's count already shows what is missing
		if (anyUnsynced(all))
		{
			content.add(wrappedText("Sync your collection log for a complete picture.", MISSING));
		}
		refresh();
	}

	/** Mortimer multi-option comparison view. */
	void showMortimer(List<Option> options)
	{
		content.removeAll();
		content.add(titleLabel("Mortimer"));
		content.add(wrappedText("Compare what each option can add to your collection log:", MISSING));

		for (Option option : options)
		{
			final JPanel card = new JPanel();
			card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
			card.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.MEDIUM_GRAY_COLOR),
				BorderFactory.createEmptyBorder(6, 0, 6, 0)));
			card.setAlignmentX(Component.LEFT_ALIGNMENT);

			final JLabel name = new JLabel(plain(option.getName()) + killCountText(option.getKillCount()));
			name.setFont(FontManager.getRunescapeBoldFont());
			name.setForeground(Color.WHITE);
			name.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(name);

			if (option.getSections().isEmpty())
			{
				card.add(wrappedText("No collection log items found.", MISSING));
			}
			else
			{
				for (Section section : option.getSections())
				{
					card.add(sectionPanel(section));
				}
			}
			content.add(card);
		}
		refresh();
	}

	// --- rendering helpers ---

	/** A monster-version section: a sub-header ("Monster x/y") plus its item rows. */
	private JPanel sectionPanel(Section section)
	{
		final JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBorder(BorderFactory.createEmptyBorder(4, 0, 2, 0));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		int obtained = 0;
		boolean anyUnsynced = false;
		for (ItemRow row : section.getRows())
		{
			if (row.isObtained())
			{
				obtained++;
			}
			if (!row.isSynced())
			{
				anyUnsynced = true;
			}
		}

		final JPanel head = new JPanel(new BorderLayout());
		head.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JLabel monster = new JLabel(plain(section.getMonster()) + killCountText(section.getKillCount()));
		monster.setFont(FontManager.getRunescapeSmallFont());
		monster.setForeground(new Color(200, 200, 200));
		head.add(monster, BorderLayout.WEST);
		final JLabel count = new JLabel(obtained + " / " + section.getRows().size());
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(obtained == section.getRows().size() && !anyUnsynced ? OBTAINED : MISSING);
		head.add(count, BorderLayout.EAST);
		panel.add(head);

		// Superior section: one line per superior count, under the heading
		if (section.getSuperiorsHere() != null)
		{
			panel.add(noteLabel(formatKills(section.getSuperiorsHere()) + " " + plain(section.getTask()) + " "
				+ superiors(section.getSuperiorsHere())));
		}
		if (section.getSuperiorsTotal() != null)
		{
			panel.add(noteLabel(formatKills(section.getSuperiorsTotal()) + " " + superiors(section.getSuperiorsTotal())
				+ " across all tasks"));
		}
		if (section.getSuperiorsHere() != null || section.getSuperiorsTotal() != null)
		{
			// a small gap so the count lines read as their own block, apart from the item rows below
			panel.add(Box.createVerticalStrut(4));
		}

		for (ItemRow row : section.getRows())
		{
			if (config.showOnlyUnobtained() && row.isObtained())
			{
				continue;
			}
			panel.add(itemRow(row));
		}
		if (anyUnsynced)
		{
			panel.add(wrappedText("Open this monster's collection log page to sync.", WARN));
		}
		return panel;
	}

	private JPanel itemRow(ItemRow row)
	{
		final JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBorder(BorderFactory.createEmptyBorder(1, 6, 1, 0));
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		final AsyncBufferedImage image = itemManager.getImage(row.getItemId());
		image.addTo(icon);
		panel.add(icon, BorderLayout.WEST);

		final JLabel name = new JLabel(plain(row.getName()));
		name.setForeground(row.isObtained() ? Color.WHITE : MISSING);

		final String rate = row.getRate();
		if (config.showDropRates() && rate != null && !rate.isEmpty())
		{
			// drop rate on a second line under the name
			final JPanel labels = new JPanel();
			labels.setLayout(new BoxLayout(labels, BoxLayout.Y_AXIS));
			name.setAlignmentX(Component.LEFT_ALIGNMENT);
			labels.add(name);

			final JLabel rateLabel = new JLabel(plain("(" + rate.replace('/', ':') + ")"));
			rateLabel.setFont(FontManager.getRunescapeSmallFont());
			rateLabel.setForeground(MISSING);
			rateLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
			labels.add(rateLabel);

			panel.add(labels, BorderLayout.CENTER);
		}
		else
		{
			panel.add(name, BorderLayout.CENTER);
		}

		final JLabel status = new JLabel();
		if (!row.isSynced())
		{
			status.setText("?");
			status.setForeground(WARN);
		}
		else if (row.isObtained())
		{
			status.setText(config.showQuantities() && row.getQuantity() > 0 ? "✓ " + row.getQuantity() : "✓");
			status.setForeground(OBTAINED);
		}
		else
		{
			status.setText("✗");
			status.setForeground(MISSING);
		}
		// which collection log page this item is on, so the heading does not have to name it
		status.setToolTipText(plain(row.isSynced()
			? "In the " + row.getPage() + " collection log."
			: "In the " + row.getPage() + " collection log. Open that page to sync."));
		panel.add(status, BorderLayout.EAST);
		return panel;
	}

	/** " (1,234 KC)" after a monster, boss or Mortimer option name; empty when unknown. */
	private static String killCountText(Integer kills)
	{
		return kills == null ? "" : " (" + formatKills(kills) + " KC)";
	}

	private static String superiors(int n)
	{
		return n == 1 ? "superior" : "superiors";
	}

	/** A small muted line under a section heading, indented like the item rows. */
	private static JLabel noteLabel(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(MISSING);
		label.setBorder(BorderFactory.createEmptyBorder(3, 6, 1, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** 1234 -> "1,234"; the kill log stops counting at "Lots!", shown as "65,535+". */
	private static String formatKills(int kills)
	{
		return kills >= KillCountTracker.LOTS ? "65,535+" : String.format("%,d", kills);
	}

	/** True when any row's status is still unknown because its collection log page has not been opened. */
	private static boolean anyUnsynced(List<ItemRow> rows)
	{
		for (ItemRow row : rows)
		{
			if (!row.isSynced())
			{
				return true;
			}
		}
		return false;
	}

	private static JLabel titleLabel(String text)
	{
		final JLabel label = new JLabel(plain(text));
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(Color.WHITE);
		label.setBorder(BorderFactory.createEmptyBorder(0, 0, 6, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel wrappedText(String text, Color color)
	{
		final JLabel label = new JLabel("<html><body style='width:150px'>" + escapeHtml(text) + "</body></html>");
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** Strips angle brackets so Swing cannot interpret the string as HTML. */
	private static String plain(String text)
	{
		return text == null ? "" : text.replace("<", "").replace(">", "");
	}

	/** Escapes text placed in wrappedText's HTML so it renders literally. */
	private static String escapeHtml(String text)
	{
		return text == null ? "" : text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	private void refresh()
	{
		content.revalidate();
		content.repaint();
	}
}

package com.slayerclog;

import com.google.inject.Provides;
import com.slayerclog.clog.CollectionLogManager;
import com.slayerclog.task.ItemGroup;
import com.slayerclog.task.KillCountTracker;
import com.slayerclog.task.MonsterMapping;
import com.slayerclog.task.MortimerInterfaceHandler;
import com.slayerclog.task.SlayerMonster;
import com.slayerclog.task.SlayerTaskTracker;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Slayer Clog Check",
	description = "Shows collection log progress for your current slayer task, and compares each option at Mortimer.",
	tags = {"slayer", "collection", "log", "clog", "task", "mortimer", "skip"}
)
public class SlayerClogPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private SlayerClogConfig config;

	@Inject
	private CollectionLogManager clogManager;

	@Inject
	private MonsterMapping mapping;

	@Inject
	private SlayerTaskTracker taskTracker;

	@Inject
	private MortimerInterfaceHandler mortimer;

	@Inject
	private KillCountTracker killCounts;

	private SlayerClogPanel panel;
	private NavigationButton navButton;

	// Konar is the only master that assigns an area, and Konar tasks are what yield Brimstone keys.
	private static final String SUPERIOR_LABEL = "Superior";
	private static final String BRIMSTONE_CHEST = "Brimstone chest";
	private static final String LARRANS_CHEST = "Larran's chest";
	private static final int KRYSTILIA_SLAYER_MASTER = 7;

	// Mortimer selection state
	private boolean mortimerActive;
	private List<String> mortimerOptions;

	// Current-task polling state
	private String lastTaskName;
	private int lastAmount = -1;

	// "New item added to your collection log: <name>."
	private static final Pattern CLOG_MESSAGE = Pattern.compile(
		"added to your collection log:\\s*(.+)", Pattern.CASE_INSENSITIVE);
	private final Map<String, Integer> itemNameToId = new HashMap<>();
	private boolean nameIndexBuilt;

	@Provides
	SlayerClogConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerClogConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new SlayerClogPanel(itemManager, config);

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/com/slayerclog/icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Slayer Clog Check")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(() ->
			{
				clogManager.load(client.getAccountHash());
				killCounts.load(client.getAccountHash());
				refreshView();
			});
		}
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
		mortimerActive = false;
		mortimerOptions = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clogManager.load(client.getAccountHash());
			killCounts.load(client.getAccountHash());
			refreshView();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			clogManager.captureOpenPage();
			// boss pages also show "X kills: N" in their header
			killCounts.captureCollectionLogHeader();
			refreshView();
		}
	}

	/** Ticks a newly obtained item from the "New item added to your collection log" message. */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final String message = event.getMessage();
		if (message == null)
		{
			return;
		}
		// "Your X kill count is: N" keeps boss kill counts current between visits to the kill logs
		if (killCounts.recordKillMessage(message))
		{
			refreshView();
			return;
		}
		// "A superior foe has appeared..." is counted against the current task: the game keeps no per-task tally
		if (killCounts.recordSuperior(message, taskTracker.getCurrentTaskName()))
		{
			refreshView();
			return;
		}
		final Matcher m = CLOG_MESSAGE.matcher(message);
		if (!m.find())
		{
			return;
		}
		final String itemName = m.group(1).replaceAll("<[^>]*>", "").replaceAll("[.\\s]+$", "").trim();
		ensureNameIndex();
		final Integer id = itemNameToId.get(itemName.toLowerCase());
		if (id != null)
		{
			clogManager.markObtained(id);
			refreshView();
		}
	}

	/** Lazily build a name -> item id index over every item in the mapping. */
	private void ensureNameIndex()
	{
		if (nameIndexBuilt)
		{
			return;
		}
		for (int id : mapping.allItemIds())
		{
			try
			{
				final String name = itemManager.getItemComposition(id).getName();
				if (name != null && !name.isEmpty())
				{
					itemNameToId.put(name.toLowerCase(), id);
				}
			}
			catch (Exception ignored)
			{
				// skip ids that have no composition
			}
		}
		nameIndexBuilt = true;
	}

	/** Polls the Slayer plugin's task config each tick; ConfigChanged is unreliable for it. */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		// The Slayer kill log has no varps, so, like the collection log, it is read whenever it is open.
		if (killCounts.captureKillLog())
		{
			refreshView();
		}

		// Mortimer selection interface: poll it (modal interfaces don't always emit WidgetLoaded).
		if (config.mortimerView())
		{
			final List<String> opts = mortimer.detect(MortimerInterfaceHandler.MORTIMER_GROUP_ID);
			if (!opts.isEmpty())
			{
				if (!mortimerActive || !opts.equals(mortimerOptions))
				{
					mortimerActive = true;
					mortimerOptions = opts;
					refreshView();
				}
				return;
			}
			if (mortimerActive)
			{
				mortimerActive = false;
				mortimerOptions = null;
				refreshView();
			}
		}

		final String name = taskTracker.getCurrentTaskName();
		final int amount = taskTracker.getAmount();
		if (!Objects.equals(name, lastTaskName) || amount != lastAmount)
		{
			lastTaskName = name;
			lastAmount = amount;
			refreshView();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// our own display options changed
		if (SlayerClogConfig.GROUP.equals(event.getGroup()))
		{
			refreshView();
		}
	}

	/** Rebuild the panel from current state. */
	private void refreshView()
	{
		if (panel == null)
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			if (mortimerActive && mortimerOptions != null && config.mortimerView())
			{
				final List<SlayerClogPanel.Option> options = new ArrayList<>();
				for (String optionName : mortimerOptions)
				{
					final SlayerMonster monster = mapping.get(optionName);
					final List<SlayerClogPanel.Section> sections =
						monster == null ? new ArrayList<>() : buildSections(monster);
					final Integer kills = config.showKillCounts() ? killCounts.get(optionName) : null;
					options.add(new SlayerClogPanel.Option(optionName, sections, kills));
				}
				updatePanel(() -> panel.showMortimer(options));
				return;
			}

			final String taskName = taskTracker.getCurrentTaskName();
			if (taskName == null)
			{
				updatePanel(() -> panel.showMessage(
					"No active slayer task.", "Get a slayer task to see its collection log progress."));
				return;
			}

			final int amount = taskTracker.getAmount();
			final String location = taskTracker.getTaskLocation();
			final SlayerMonster monster = mapping.get(taskName);
			final List<SlayerClogPanel.Section> sections =
				monster == null ? new ArrayList<>() : buildSections(monster);
			if (location != null)
			{
				addChest(sections, BRIMSTONE_CHEST);
			}
			if (client.getVarbitValue(VarbitID.SLAYER_MASTER) == KRYSTILIA_SLAYER_MASTER)
			{
				addChest(sections, LARRANS_CHEST);
			}
			final Integer kills = config.showKillCounts() ? killCounts.get(taskName) : null;
			updatePanel(() -> panel.showTask(taskName, amount, location, sections, kills));
		});
	}

	/** Build one display Section per monster version of the task (base monster, Superior, boss). */
	private List<SlayerClogPanel.Section> buildSections(SlayerMonster monster)
	{
		// one section per monster: groups from several pages merge, each row keeps its page
		final Map<String, List<SlayerClogPanel.ItemRow>> byMonster = new LinkedHashMap<>();
		for (ItemGroup group : monster.getGroups())
		{
			if (!config.showSuperior() && SUPERIOR_LABEL.equals(group.getMonster()))
			{
				continue;
			}
			final List<SlayerClogPanel.ItemRow> rows =
				byMonster.computeIfAbsent(group.getMonster(), k -> new ArrayList<>());
			for (int itemId : group.getItems())
			{
				final String name = itemManager.getItemComposition(itemId).getName();
				final Boolean status = clogManager.isObtained(group.getPage(), itemId);
				final boolean synced = status != null; // null = status still unknown (page not synced)
				final boolean obtained = Boolean.TRUE.equals(status);
				final int quantity = clogManager.getQuantity(group.getPage(), itemId);
				final String rate = group.getRates().get(itemId);
				rows.add(new SlayerClogPanel.ItemRow(itemId, name, obtained, quantity, synced, rate, group.getPage()));
			}
		}
		final List<SlayerClogPanel.Section> sections = new ArrayList<>();
		for (Map.Entry<String, List<SlayerClogPanel.ItemRow>> e : byMonster.entrySet())
		{
			// the task's own kill log count is shown by the task/option name, so sections do not repeat it
			final Integer kills = config.showKillCounts() ? killCounts.getForSection(e.getKey(), monster.getName()) : null;
			// Superior section: superiors seen on this task, and the all-task total
			final boolean superior = SUPERIOR_LABEL.equals(e.getKey());
			Integer here = null;
			if (superior && config.showSuperiorTracked())
			{
				final Integer seen = killCounts.superiorsOnTask(monster.getName());
				here = seen == null ? 0 : seen;
			}
			final Integer total = superior && config.showSuperiorTotal() ? killCounts.superiorsKilled() : null;
			sections.add(new SlayerClogPanel.Section(e.getKey(), e.getValue(), kills, here, total, monster.getName()));
		}
		return sections;
	}

	/** Adds a chest entry from the mapping as extra sections, when its slayer master condition applies. */
	private void addChest(List<SlayerClogPanel.Section> sections, String key)
	{
		final SlayerMonster chest = mapping.get(key);
		if (chest != null)
		{
			sections.addAll(buildSections(chest));
		}
	}

	private void updatePanel(Runnable update)
	{
		final SlayerClogPanel current = panel;
		if (current == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (panel == current)
			{
				update.run();
			}
		});
	}
}

